INSERT INTO public.kayla_benchmark_cases (question, category, expected_facts, must_not_say, is_active)
SELECT v.q, 'clinical', v.e, v.m, true FROM (VALUES
('How do I dictate a note?', 'Open AI Note-Taking in the clinic workspace, choose a supplied fictional visit transcript and generate a sample draft; every statement links to cited transcript lines and the doctor reviews and decides separately. Live recording of real visits and real patient records are not available in the preview.', 'that it records real patient visits today, or that the note is final without a doctor signing'),
('What is the Delegation Desk?', 'Shows the clerical tasks Kayla and the Agentic AI Employees prepare for the doctor (chart prep, note drafts, authorization packets, follow-up lists) and what still needs a human decision; the doctor approves, edits or sends back items as a rehearsal. Fictional tasks only; nothing is sent, booked or billed.', 'that it sends orders, books appointments, bills or prescribes'),
('How do I follow a case through Doctor Day?', 'Connected Doctor Day: select one fictional case and move through its illustrative schedule slot, historical chart, transcript, note and follow-up preparation. Slots are not booked or completed visits, and signing a sample note never sends anything to a patient.', 'that the slots are real booked appointments'),
('How does pre-visit chart prep work?', 'Pre-Visit Chart Prep organizes fixed fictional prior-visit excerpts and highlights missing information with source links, to inspect before reviewing a draft. It does not infer current findings, accept pasted chart text or save approval.', 'that it diagnoses or infers current findings'),
('What does the medical chronology show?', 'Medical Chronology orders fixed dated fictional records into a timeline, keeps undated records separate, and flags cite exact excerpts. It never invents dates or turns planned visits into completed care.', 'invented dates'),
('When can I sign a report?', 'An authorized clinic reviewer inspects the source evidence and makes a separate sign or reject decision; only source-verified, doctor-signed sample notes can produce a reviewed-report PDF. Unsigned or rejected notes cannot become signed reports, and a typed name is a sample attestation, not a verified medical license.', 'that the typed signature verifies a medical license'),
('What is the CME review?', 'CME means Compulsory Medical Examination. Kayla groups cited excerpts from built-in fictional record packets into drafts; authorized clinic reviewers make the decisions. Real uploads are locked and the AI draft is not a medical or causation decision.', 'that real files can be uploaded today, or that Kayla decides causation'),
('How does medication review assistance work?', 'It highlights exact fictional medicine mentions and gaps, separating past use, future discussion and unknown reconciliation. It does not prescribe, recommend doses, screen interactions or save medication approval.', 'that it checks drug interactions or recommends doses'),
('What can the Clinical Data Explorer search?', 'It rehearses medication and laboratory (creatinine) queries against four synthetic cases, showing matched, excluded and unknown evidence; you confirm threshold, units and dates, and changing criteria clears results. No real-record search, export or recruitment.', 'that it searches real patient records'),
('What is a care guide?', 'Care Guide gives fixed English and Spanish drafts that paraphrase the fictional visit plan and cite exact source quotes, with missing instructions left visible. Nothing is approved or delivered to patients in the preview.', 'that guides are sent to patients'),
('What does the billing documentation check do?', 'It shows fixed documentation findings tied to exact fictional transcript quotes, kept separate from payer or reimbursement decisions. It does not pick billing codes, visit levels, payment eligibility or submit claims.', 'a specific billing code recommendation, or that claims are submitted'),
('How does prior authorization work?', 'Prior Authorization prepares a fixed fictional packet with exact quotations and shows missing information for review rehearsal. No signature, export, insurer submission or coverage approval.', 'that it submits to insurers or gets approval'),
('What is Kenya IDSR reporting?', 'IDSR means Integrated Disease Surveillance and Response, Kenya''s notifiable-disease reporting. The screen rehearses preparing reports from fictional cases with versioned sample exports. No real report is sent and no reporting access is granted.', 'that reports are sent to the Kenya Ministry of Health'),
('What is the National Health Exchange?', 'A readiness chart for connecting to national health information exchanges such as Kenya''s, using fixed sample evidence before any real connection. Sample evidence is not national acceptance or a live connection.', 'that it is connected to a live national exchange'),
('How do I join the doctor pilot?', 'Request access at health.1325.ai/pilot and agree to use test records only; Thomas personally approves each request; open the approval link on the same device; start with Connected Doctor Day then AI Note-Taking; add made-up records in Pilot test records; send feedback through Doctor Evaluation or Partner@1325.AI. Real patient information is not allowed yet.', 'that real patient information may be entered, or a contact@ or business@ email address'),
('What are pilot test records?', 'Pilot test records let a clinic create invented test people to practice the flow from schedule through note, billing and inbox, then delete them. Never enter real people or real health information.', 'that real people can be added'),
('How do I change my department or location?', 'Use the department selector (for example Primary Care) and the fictional location picker; they change which examples and layout you see, and the saved workspace remembers your view on this device. Changing location does not move records or change clinic access.', 'that changing location moves records or grants access to another clinic'),
('Is 1325 Clinical a complete certified EMR?', 'No. It is an EMR/EHR in development, currently a private sample-data preview, not yet a complete or certified live system. Real patient records remain locked until healthcare clearance.', 'that it is certified, HIPAA-certified, clinically validated or ready for real patients')
) AS v(q, e, m)
WHERE NOT EXISTS (SELECT 1 FROM public.kayla_benchmark_cases k WHERE k.question = v.q);